window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"WUsRJ4TLbio","speaker":"Masoud Pezeshkian","role":"President","country":"Iran","region":"Middle East","url":"https://www.youtube.com/watch?v=WUsRJ4TLbio","date":"20260923","title":"🇮🇷 Iran - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1108,"words":2092,"counts":{"claims":28,"promises":5,"attacks":12},"topics":[{"topic":"Iran nuclear","share":0.1295,"seconds":144},{"topic":"Iran defense","share":0.1195,"seconds":132},{"topic":"UN Charter","share":0.0736,"seconds":82},{"topic":"Iran school bombing","share":0.0627,"seconds":70},{"topic":"Palestine","share":0.0621,"seconds":69},{"topic":"Regional resistance","share":0.0595,"seconds":66},{"topic":"Strait of Hormuz","share":0.0594,"seconds":66},{"topic":"US sanctions","share":0.0592,"seconds":66},{"topic":"Regional security","share":0.0574,"seconds":64},{"topic":"Israel nuclear","share":0.0569,"seconds":63},{"topic":"Iran stability","share":0.0559,"seconds":62},{"topic":"US accusations","share":0.0554,"seconds":61},{"topic":"Iran attacks","share":0.0552,"seconds":61},{"topic":"Gaza conflict","share":0.0545,"seconds":60},{"topic":"Iran sanctions","share":0.0393,"seconds":44}],"timeline":[[8,70,"US accusations"],[75,145,"Iran school bombing"],[146,207,"Iran attacks"],[209,269,"Gaza conflict"],[270,331,"Iran defense"],[332,394,"Iran stability"],[395,477,"Iran nuclear"],[478,540,"Iran nuclear"],[541,607,"Strait of Hormuz"],[608,676,"Palestine"],[677,743,"Regional resistance"],[744,815,"Iran defense"],[817,880,"Israel nuclear"],[881,947,"US sanctions"],[948,1011,"Regional security"],[1012,1094,"UN Charter"],[1095,1138,"Iran sanctions"]],"stances":{"US accusations":"Masoud Pezeshkian states that the United States president has labeled Iran as terrorists and asserts that Iran is actually the victim of terrorism.","Iran school bombing":"Masoud Pezeshkian states that the United States and Israel bombed a school in Iran, resulting in the deaths of innocent children.","Iran attacks":"Masoud Pezeshkian states that Iran has only defended itself against attacks by America and Israel without targeting civilian populations.","Gaza conflict":"Masoud Pezeshkian asserts that Israel is committing genocide and acts as a terrorist against civilians in Gaza while falsely labeling others as terrorists.","Iran defense":"Masoud Pezeshkian asserts that Iran has not attacked any country for two centuries and has only defended itself steadfastly while criticizing powerful nations for creating instability.","Iran stability":"Masoud Pezeshkian states that Iran seeks power for self-defense and progress rather than aggression, while attributing recent internal disruptions to foreign training by Israel and America.","Iran nuclear":"Masoud Pezeshkian asserts that Iran's nuclear technology is essential for peaceful progress and national development, rejecting the notion that it requires international permission.","Strait of Hormuz":"Masoud Pezeshkian asserts that Iran cannot allow other nations to use the Strait of Hormuz for aggression while denying Iran access, and states that expanding warfare will not bring security.","Palestine":"Masoud Pezeshkian asserts that lasting peace in West Asia is impossible without justice for Palestine and that resistance will continue as long as occupation persists.","Regional resistance":"Masoud Pezeshkian argues that resistance is an inherent human response to aggression and displacement, and that regional issues should be resolved by regional countries without interference from outside powers.","Israel nuclear":"Masoud Pezeshkian asserts that Israel possesses nuclear weapons and faces no inspections while Iran is subjected to sanctions despite having no such weapons.","US sanctions":"Masoud Pezeshkian argues that US sanctions target innocent populations to achieve illegitimate goals and calls for a single standard of application for all countries.","Regional security":"Masoud Pezeshkian argues that the world must avoid an era dominated by bullying powers and military force, advocating instead for dialogue, diplomacy, and collective security.","UN Charter":"Masoud Pezeshkian argues that a just international order must be based on human dignity and justice for all, and asserts that recent statements by the US President contradict UN principles.","Iran sanctions":"Masoud Pezeshkian states that Iranian resistance will increase under pressure and that the country is ready for dialogue without accepting force."},"claims":[{"t":63,"quote":"The United States president described us as terrorists.","topic":"US accusations","kind":"fact"},{"t":68,"quote":"We have been the victims of terrorism.","topic":"US accusations","kind":"fact"},{"t":90,"quote":"I come from an Iran where in truth they bombed a school. You see these children These children perished under bombs with weapons used by the United States and Israel.","topic":"Iran school bombing","kind":"fact"},{"t":122,"quote":"Lammer, one of the small cities in a province in Iran, a sports hall where children were busy The United States by using weapons with multiple warheads, targeted that sports hall.","topic":"Iran school bombing","kind":"fact"},{"t":189,"quote":"America and Israel attacked us equipped with the latest technology and weapon systems.","topic":"Iran attacks","kind":"fact"},{"t":224,"quote":"When I took over the responsibilities as president, they assassinated Ismael Hana in Iran on the day of my inauguration.","topic":"Gaza conflict","kind":"fact"},{"t":241,"quote":"Over 80,000 innocent civilians have been murdered, brutally murdered.","topic":"Gaza conflict","kind":"number"},{"t":324,"quote":"200 years, for the past two centuries, Iran has not attacked any country or any territory.","topic":"Iran defense","kind":"fact"},{"t":368,"quote":"In the past seven months, our people have been in the streets every night demonstrating in support of their land, of their homeland","topic":"Iran stability","kind":"fact"},{"t":391,"quote":"For 7 months, day and night, they've been present in the streets","topic":"Iran stability","kind":"number"},{"t":464,"quote":"for our sick people is cure and treatment for the agricultural sector is food security for industries advancement and progress and supply of electrical energy","topic":"Iran nuclear","kind":"fact"},{"t":497,"quote":"We say it clearly, no nuclear weapons and no limitations to peaceful nuclear technology.","topic":"Iran nuclear","kind":"fact"},{"t":535,"quote":"That's why Iran does not see her neighbors as security rivals.","topic":"Iran nuclear","kind":"fact"},{"t":570,"quote":"They close access for us to our own waterway. they keep supplying missiles and deadly tech military technologies to bring in security to all of the lands surrounding that waterway.","topic":"Strait of Hormuz","kind":"fact"},{"t":622,"quote":"For decades, resolutions have been adopted. Yet occupation and viol violence have continued.","topic":"Palestine","kind":"fact"},{"t":667,"quote":"Gaza, despite relentless killing and widespread devastation, has strengthened the people's faith in resistance.","topic":"Palestine","kind":"fact"},{"t":677,"quote":"And resistance cannot be destroyed by bombs and siege. This is human nature.","topic":"Regional resistance","kind":"fact"},{"t":685,"quote":"If a human being is driven from his or her land, they will resist.","topic":"Regional resistance","kind":"fact"},{"t":771,"quote":"Iran has never ever been an aggressor, has never started a war and has always shown her commitment to the negotiating table.","topic":"Iran defense","kind":"fact"},{"t":781,"quote":"They imposed the war on us. But we proved we have proven that we're not afraid of fighting of war. won a war that is defensive in nature","topic":"Iran defense","kind":"fact"},{"t":827,"quote":"Israel has murdered savagely over 70,000 innocents in Gaza","topic":"Israel nuclear","kind":"number"},{"t":847,"quote":"during her shameful life has not allowed a single inspection","topic":"Israel nuclear","kind":"fact"},{"t":881,"quote":"Those who are ill, innocent people, the poor, the least privileged in our society are the targets of these sanctions.","topic":"US sanctions","kind":"fact"},{"t":888,"quote":"And this is what the United States seeks to do with all countries to sacrifice the population of a country in order to her illegitimate goals.","topic":"US sanctions","kind":"fact"},{"t":948,"quote":"But we see that this will become a world much more dangerous for all of us.","topic":"Regional security","kind":"fact"},{"t":975,"quote":"Terrorism replaces politics and negotiations and war replaces dialogue and diplomacy.","topic":"Regional security","kind":"fact"},{"t":1087,"quote":"everything uttered about our country goes against the very essence and charter and the spirit of the United Nations","topic":"UN Charter","kind":"fact"},{"t":1096,"quote":"the resistance of the Iranian people will only increase in the face of sanctions, increased pressure, increased increased bullying.","topic":"Iran sanctions","kind":"fact"}],"promises":[{"t":485,"quote":"We will not we will not bow our head and give up the right that is inherently ours.","topic":"Iran nuclear","kind":"promise"},{"t":588,"quote":"We will not succumb to The expansion of warfare","topic":"Strait of Hormuz","kind":"promise"},{"t":794,"quote":"we will stand in defense of our beloved Iran, our homeland, until our last breath.","topic":"Iran defense","kind":"promise"},{"t":1105,"quote":"We will never bow our head or bend at the knee.","topic":"Iran sanctions","kind":"promise"},{"t":1117,"quote":"we are ready for dialogue and diplomacy and negotiations without accepting the language of force.","topic":"Iran sanctions","kind":"promise"}],"attacks":[{"t":134,"quote":"The United States by using weapons with multiple warheads, targeted that sports hall.","topic":"Iran school bombing","target":"United States"},{"t":159,"quote":"Those who are terrorists and train and protect terrorists describe us as such.","topic":"Iran attacks","target":"Unnamed opponents"},{"t":233,"quote":"Israel targets any neighborhood in any city in any province, commits assassinations like a true terrorist in Gaza.","topic":"Gaza conflict","target":"Israel"},{"t":252,"quote":"They are committing genocide by using the to so-called technologies that they have at their disposal. Then they label others as terrorists.","topic":"Gaza conflict","target":"Israel"},{"t":315,"quote":"They seem to be the protectors and creators of instability and destruction.","topic":"Iran defense","target":"Unnamed opponents"},{"t":320,"quote":"Whomever they wish to discredit, they label them as terrorists.","topic":"Iran defense","target":"Unnamed opponents"},{"t":380,"quote":"those who were equipped and trained and armed by Israel and America to cause disruption in the security of their country","topic":"Iran stability","target":"United States"},{"t":744,"quote":"And a few words with those who are responsible for having planned and carried out aggressions against our country.","topic":"Iran defense","target":"Unnamed opponents"},{"t":817,"quote":"Atomic and nuclear bombs are in the hands of the Israeli regime","topic":"Israel nuclear","target":"Israel"},{"t":827,"quote":"Israel has murdered savagely over 70,000 innocents in Gaza","topic":"Israel nuclear","target":"Israel"},{"t":893,"quote":"sacrifice the population of a country in order to her illegitimate goals","topic":"US sanctions","target":"United States"},{"t":1087,"quote":"everything uttered about our country goes against the very essence and charter and the spirit of the United Nations","topic":"UN Charter","target":"United States"}],"greece":[],"said":[{"topic":"Iran nuclear","said":0.1295,"reported":0.0638,"articles":3},{"topic":"Iran defense","said":0.1195,"reported":0.1064,"articles":5},{"topic":"UN Charter","said":0.0736,"reported":0.0851,"articles":4},{"topic":"Iran school bombing","said":0.0627,"reported":0.0426,"articles":2},{"topic":"Palestine","said":0.0621,"reported":0.0213,"articles":1},{"topic":"Regional resistance","said":0.0595,"reported":0.0,"articles":0},{"topic":"Strait of Hormuz","said":0.0594,"reported":0.0851,"articles":4},{"topic":"US sanctions","said":0.0592,"reported":0.1702,"articles":8},{"topic":"Regional security","said":0.0574,"reported":0.0851,"articles":4},{"topic":"Israel nuclear","said":0.0569,"reported":0.0213,"articles":1},{"topic":"Iran stability","said":0.0559,"reported":0.0851,"articles":4},{"topic":"US accusations","said":0.0554,"reported":0.1277,"articles":6},{"topic":"Iran attacks","said":0.0552,"reported":0.0851,"articles":4},{"topic":"Gaza conflict","said":0.0545,"reported":0.0213,"articles":1},{"topic":"Iran sanctions","said":0.0393,"reported":0.0,"articles":0}],"pickup":[{"outlet":"TVXS","date":"2026-09-22","title":"Ιράν / Στις ΗΠΑ Πεζεσκιάν και Αραγτσί για τη Γενική Συνέλευση του ΟΗΕ – «Θα υπερασπιστούμε σθεναρά τις θέσεις μας, ο ιρανικός λαός άντεξε»","url":"https://tvxs.gr/news/kosmos/ampas-aragtsi-stis-ipa-o-ypex-toy-iran-gia-ti-geniki-syneleysi-toy-oie","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-22","title":"Πεζεκιάν: «Ο ιρανικός λαός άντεξε – Θα υπερασπιστούμε σθεναρά τις θέσεις μας» – Μήνυμα για τη ΓΣ του ΟΗΕ","url":"https://www.in.gr/2026/09/22/world/pezekian-o-iranikos-laos-antekse-tha-yperaspistoume-sthenara-tis-theseis-mas-minyma-gia-ti-gs-tou-oie","tone":"neutral"},{"outlet":"ThePressProject","date":"2026-09-22","title":"Reuters: Το Ιράν δηλώνει έτοιμο να ανοίξει τα Στενά του Ορμούζ μέσα σε επτά μέρες υπό όρους","url":"https://thepressproject.gr/reuters-to-iran-dilonei-etoimo-na-anoixei-ta-stena-tou-ormouz-mesa-se-epta-meres-ypo-orous","tone":"neutral"},{"outlet":"ThePressProject","date":"2026-09-22","title":"Στη Νέα Υόρκη Πεζεσκιάν και Αραγτσί για τη Γενική Συνέλευση του ΟΗΕ – «Θα υπερασπιστούμε σθεναρά τις θέσεις μας»","url":"https://thepressproject.gr/sti-nea-yorki-pezeskian-kai-aragtsi-gia-ti-geniki-synelefsi-tou-oie-tha-yperaspistoume-sthenara-tis-theseis-mas","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-22","title":"Ιράν: «Έτοιμοι να ανοίξουμε τα Στενά του Ορμούζ σε 7 μέρες» αν οι ΗΠΑ άρουν τον ναυτικό αποκλεισμό","url":"https://www.newsbomb.gr/kosmos/story/1765177/iran-etoimoi-na-anoiksoume-ta-stena-tou-ormoyz-se-7-meres-an-oi-ipa-aroun-ton-naftiko-apokleismo","tone":"neutral"},{"outlet":"Alpha","date":"2026-09-22","title":"Ιράν: Διπλωματία για να ανοίξουν ξανά τα Στενά του Ορμούζ","url":"https://www.alphatv.gr/kosmos/iran-diplomatia-gia-na-anoixoun-xana-ta-stena-tou-ormouz","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-23","title":"Πεζεσκιάν στον ΟΗΕ: Οι Ιρανοί είναι θύματα τρομοκρατίας, αλλά δεν θα λυγίσουν ποτέ","url":"https://www.in.gr/2026/09/23/world/pezeskian-ston-oie-oi-iranoi-einai-thymata-tromokratias-alla-den-tha-lygisoun-pote","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-23","title":"Πεζεσκιάν στον ΟΗΕ: «Το Ιράν είναι θύμα τρομοκρατίας» – «ΗΠΑ και Ισραήλ δολοφόνησαν τα παιδιά μας»","url":"https://www.efsyn.gr/kosmos/1473162/pezeskian-ston-oie-to-iran-einai-thyma-tromokratias-ipa-kai-israil-dolofonisan-toys-polites-mas","tone":"neutral"},{"outlet":"Avgi","date":"2026-09-23","title":"«Ο Τραμπ πρέπει να μάθει ότι οι απειλές ενώνουν το ιρανικό έθνος»","url":"https://www.avgi.gr/diethni/528101_o-tramp-prepei-na-mathei-oti-oi-apeiles-enonoyn-iraniko-ethnos","tone":"neutral"},{"outlet":"TVXS","date":"2026-09-23","title":"Πεζεσκιάν στον ΟΗΕ / Οργισμένη απάντηση στον Τραμπ – «Εσείς είστε οι τρομοκράτες»","url":"https://tvxs.gr/news/kosmos/pezeskian-ston-oie-orgismeni-apantisi-ston-tramp-eseis-eiste-oi-tromokrates","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-23","title":"Ιράν -Πεζεσκιάν: «Δεν θα σκύψουμε ποτέ το κεφάλι μας» στον Τραμπ - Αποχώρησε η αντιπροσωπεία των ΗΠΑ","url":"https://www.newsbomb.gr/kosmos/story/1765463/iran-pezeskian-den-tha-skypsoume-pote-to-kefali-mas-ston-tramp","tone":"neutral"}],"transcript":[{"t":8,"topic":"US accusations","text":"The assembly will hear an address by His Excellency Masud Peshkan, President of the Islamic Republic of Iran. I request protocol to escort his excellency and invite him to address the In the name of God, the most compassionate, the most merciful. Mr. President, Mr. Secretary General. Excellencies, ladies and gentlemen, I had prepared a speech to present to you yesterday. The United States president described us as terrorists. We have been the victims of terrorism."},{"t":75,"topic":"Iran school bombing","text":"I come from an Iran in which our esteemed supreme leader was without any framework or reason. I come from an Iran where in truth they bombed a school. You see these children These children perished under bombs with weapons used by the United States and Israel. They were innocent. Had committed no crimes. Lammer, one of the small cities in a province in Iran, a sports hall where children were busy The United States by using weapons with multiple warheads, targeted that sports hall."},{"t":146,"topic":"Iran attacks","text":"They martyed, assassinated our scientists, our men, women, and children. innocent children whom in truth had committed no crimes, no sins. Those who are terrorists and train and protect terrorists describe us as such. We have only defended ourselves. We are not The our innocent people have been the targets of cowardly attacks and aggressions imposed upon our country. And we defended ourselves with utmost strength. America and Israel attacked us equipped with the latest technology and weapon systems. And our people stood steadfast. Yes, they did hit us, but we did not bend the knee. We did not bow our head. We responded, but we did not hit civilian populations."},{"t":209,"topic":"Gaza conflict","text":"They came into surrounding territories by and targeted our universities, our health care centers, our schools, our hospitals, our infrastructures. All of it against international law. When I took over the responsibilities as president, they assassinated Ismael Hana in Iran on the day of my inauguration. Israel targets any neighborhood in any city in any province, commits assassinations like a true terrorist in Gaza. Over 80,000 innocent civilians have been murdered, brutally murdered. Hundreds of thousands have been displaced. They are committing genocide by using the to so-called technologies that they have at their disposal. Then they label others as terrorists. Are we the sources of instability? We only seek to live independently. We are the ones who cause instability."},{"t":270,"topic":"Iran defense","text":"Those who are committing terrorism and committing crimes, are they the protectors of peace and stability? None of the international laws have been adhered to by them. This is some This is what we're facing. We don't want anything. We have received our response. We need because a people who is which is unable to defend itself will be trampled upon in today's world. We live in a world in which the powerful instead of thinking about humanity, justice, fairness, and democracy, they seem to be the protectors and creators of instability and destruction. Whomever they wish to discredit, they label them as terrorists. 200 years, for the past two centuries, Iran has not attacked any country or any territory. But we've always defended ourselves steadfastly."},{"t":332,"topic":"Iran stability","text":"But now we're being accused of being source of instability in the region. We're labeled terrorists. And this has made it so that the path that we have chosen for ourselves requires power to defend ourselves. We do not seek power in order to attack or commit aggression. We seek energy for progress, not to threaten societies with weapons. And we wish to cooperate and collaborate for security. the people of Iran. In the past seven months, our people have been in the streets every night demonstrating in support of their land, of their homeland, so as to not allow those who were equipped and trained and armed by Israel and America to cause disruption in the security of their country. For 7 months, day and night, they've been present in the streets."},{"t":395,"topic":"Iran nuclear","text":"They are our source of power and our support. And that's why we stand fast. Iran must be powerful so as to avoid being threatened, to avoid its future being threatened. We do not wish to use our power for hegemony. And we do not seek our security and the insecurity of others. Iran's defense. Our defensive systems have been built so that no one can think that bombing of Iranian cities will go unanswered. That is why we have the military power we do for defense. But we say it clearly in order to defend our country, we do not seek anyone's permission or approval. We seek energy for progress. For years there have been they have labeled centrifuges uh international sanctions other labels when it comes to our nuclear technology but for our country peaceful nuclear technology is part of our inherent progress for our sick people is cure and treatment for the agricultural sector is food security for industries advancement and progress and supply of electrical energy."},{"t":478,"topic":"Iran nuclear","text":"Iran does not accept for nuclear technology to be at the exclusive disposal of some of a handful. We will not we will not bow our head and give up the right that is inherently ours. We say it clearly, no nuclear weapons and no limitations to peaceful nuclear technology. Our peace will not come in the field of they must give the needed security to the people and nation of Iran. We seek cooperation in order to have security. We live in a region in which warfare knows no borders. Crisis in one land will spill into the surrounding That's why Iran does not see her neighbors as security rivals."},{"t":541,"topic":"Strait of Hormuz","text":"We want to have strong neighbors in waters in the street of Hormones. We do not we cannot let some have free access and gain their interest from a waterway while at the same time using that waterway to impose their aggressions upon us to impose insecurity upon us to forbid us access to our own waterways. They close access for us to our own waterway. they keep supplying missiles and deadly tech military technologies to bring in security to all of the lands surrounding that waterway. We will not succumb to The expansion of warfare will not result in security. One cannot create chaos for the coastal seeking naval security."},{"t":608,"topic":"Palestine","text":"Excellencies, visav Palestine, Palestine remains an open wound on the conscience of the international community and Gaza remains a symbol of the failure of international mechanisms to prevent civilian suffering. For decades, resolutions have been adopted. Yet occupation and viol violence have continued. We cannot speak of peace while ignoring Palestine. Lasting peace in West Asia is impossible without justice for Palestine. As long as occupation, aggression and injustice persist in the world, resistance will continue. If it is weakened in one form, it will reemerge in others, perhaps stronger Gaza, despite relentless killing and widespread devastation, has strengthened the people's faith in resistance."},{"t":677,"topic":"Regional resistance","text":"And resistance cannot be destroyed by bombs and siege. This is human nature. If a human being is driven from his or her land, they will resist. If their homes are subjected to bombings and aggression and attacks, they will resist. What other choice do they have? Succumb to bullying to be driven from their homes, from their lands, and remain silent in the face of these threats and dangers. And when they defend themselves, they're labeled as The language makes it unfortunately clear the type of world that we're living in today. Our regional issues must be resolved in the region at the hands of the countries in the region without being becoming a toy in the hands of outside aggressors. No relationship with the foreign power can become the tools of threatening neighboring countries in the region."},{"t":744,"topic":"Iran defense","text":"And a few words with those who are responsible for having planned and carried out aggressions against our country. And our people have experienced firsthand the result of their deadly aggression. and they have tested the strength and the steadfastness of Iran and they have learned that Iran cannot be made to surrender. Iran has never ever been an aggressor, has never started a war and has always shown her commitment to the negotiating table. They imposed the war on us. But we proved we have proven that we're not afraid of fighting of war. won a war that is defensive in nature and we will stand in defense of our beloved Iran, our homeland, until our last breath. Ladies and gentlemen, the topic of this gathering is mutual trust that cannot be achieved through words only, but by abstaining from using double standards."},{"t":817,"topic":"Israel nuclear","text":"Atomic and nuclear bombs are in the hands of the Israeli regime, but the are requested to come to Iran. Israel has murdered savagely over 70,000 innocents in Gaza, but Iran, while behind the table of negotiation, was bombed. Israel has the bombs, has weapons of mass destruction, not a member of the non-prololiferation treaty during her shameful life has not allowed a single inspection, but they are rewarded by all the means necessary for them to be able to bomb any capital in the region at will. I will repeat, the nuclear weapon is in Israel, but the inspectors in Iran. Israel kills, but Iran is subject to sanctions. This is a true tragedy, which would make anyone hearing it laugh at best. They kill, we are sanctioned, we are punished."},{"t":881,"topic":"US sanctions","text":"Those who are ill, innocent people, the poor, the least privileged in our society are the targets of these sanctions. And this is what the United States seeks to do with all countries to sacrifice the population of a country in order to her illegitimate goals. If we seek true peace and stability, we must apply a single standard for all. Iran does not seek special treatment. We seek equal We assume the responsibility accept the responsibility that comes with it. But Iran during her pride pr prideful history has learned the following lesson. A world without power is dangerous. But a world that only understands the language of war and bully will not be safe. When we seek to have agendas to implement that only adhere to the benefits of a few privileged, we will have a world in disarray."},{"t":948,"topic":"Regional security","text":"But we see that this will become a world much more dangerous for all of us. We must not allow the 21st century to go back to an era of only the powerful and the bullying powers and the hegeimons. We must not build a world in which military power legitimacy. Terrorism replaces politics and negotiations and war replaces dialogue and diplomacy. Iran extends her hand towards the world. we invite the world. We call the world not out of weakness but out of a deep belief in our own power and steadfastness to cooperate and collaborate because of a deep belief that no one in this region will have security alone. Either we will build it or we will have to live under insecurity together."},{"t":1012,"topic":"UN Charter","text":"We seek to think about a worthy future in which security, fairness, justice, human dignity will become unalienable rights for all people. For all humans. A future in which no people are driven to the sidelines. No voice is lost in the chaos of power and no power has will have the right to determine the future of a people other than those people themselves. If we truly seek to have an order based on international law and standards, it must be based in justice, common human will, uplifting human dignity because a peace that does not encompass all is no peace. and fairness and justice that does not embrace all is not worthy of being called justice and fairness. But going back to the words of the president of the United States yesterday shows those who are experts in international law and dialogue and diplomacy and basic human standards that everything uttered about our country goes against the very essence and charter and the spirit of the United Nations."},{"t":1095,"topic":"Iran sanctions","text":"He must know that the resistance of the Iranian people will only increase in the face of sanctions, increased pressure, increased increased bullying. We will never bow our head or bend at the knee. must be understood by Mr. Trump and those who seek to bully us that we are ready for dialogue and diplomacy and negotiations without accepting the language of force. I truly appreciate your time and presence here. May God bless you all. &gt;&gt; On behalf of the assembly, I wish to thank the president of the Islamic Republic of Iran."}],"compare":[{"topic":"Iran","share":0.1195,"mean":0.0132,"rank":6,"others":25},{"topic":"Israel–Palestine","share":0.1166,"mean":0.0521,"rank":27,"others":76},{"topic":"International Law & Order","share":0.1149,"mean":0.0601,"rank":40,"others":102},{"topic":"UN & its reform","share":0.0736,"mean":0.2054,"rank":159,"others":170},{"topic":"Strait of Hormuz","share":0.0594,"mean":0.0028,"rank":5,"others":5},{"topic":"Sanctions","share":0.0592,"mean":0.0028,"rank":6,"others":5},{"topic":"Regional Security","share":0.0574,"mean":0.0043,"rank":8,"others":12},{"topic":"Nuclear Weapons","share":0.0569,"mean":0.0022,"rank":4,"others":6}]};
